using AfriWallet.Fraud.DeviceRisk.Application.Abstractions;using AfriWallet.Fraud.DeviceRisk.Domain.Signals;namespace AfriWallet.Fraud.DeviceRisk.Infrastructure;public sealed class SandboxFraudSignalReader:IFraudSignalReader{private readonly List<FraudSignalSnapshot> _signals=[];public void Add(FraudSignalSnapshot signal)=>_signals.Add(signal);public Task<IReadOnlyCollection<FraudSignalSnapshot>> GetBySubjectAsync(string type,string id,DateTimeOffset from,CancellationToken ct=default){ct.ThrowIfCancellationRequested();IReadOnlyCollection<FraudSignalSnapshot> result=_signals.Where(x=>string.Equals(x.SubjectType,type,StringComparison.OrdinalIgnoreCase)&&string.Equals(x.SubjectId,id,StringComparison.Ordinal)&&x.OccurredAt>=from).OrderBy(x=>x.OccurredAt).ToArray();return Task.FromResult(result);}}